def main():
 c=get_settings(); d=make_session_factory(c.database_url)(); r=SessionRuntime(bootstrap(c)); source=d.scalar(select(AssessmentInstance).where(AssessmentInstance.status=="CLOSED").order_by(AssessmentInstance.closed_at.desc())); sr=d.scalar(select(AssessmentResponse).where(AssessmentResponse.assessment_instance_id==source.id)); s=r.create_session(d,d.get(Session,source.session_id).study_version_id,build_id="fault-third-failure",institutional_id="fault-third-"+uuid.uuid4().hex[:10],commit=False); a=d.get(Attempt,s.current_attempt_id); a.sequence_in_transition=3
 item=AssessmentInstance(session_id=s.id,attempt_id=a.id,transition_id=a.transition_id,assessment_family_id=source.assessment_family_id,assessment_form_id=source.assessment_form_id,status="AWAITING_EVALUATION",candidate_form_ids=source.candidate_form_ids,selection_method="FAULT",selection_audit={},blueprint_snapshot=source.blueprint_snapshot,resolved_component_ids=source.resolved_component_ids,frozen_public_snapshot=source.frozen_public_snapshot,frozen_private_snapshot=source.frozen_private_snapshot,frozen_package_fingerprint=source.frozen_package_fingerprint,frozen_schema_version=source.frozen_schema_version,frozen_metadata_snapshot=source.frozen_metadata_snapshot,delivery_status="DEVELOPMENT_ONLY",frozen_at=datetime.now(timezone.utc)); d.add(item); d.flush(); opts={q['id']:next(x['id'] for x in q['options'] if x['id']!=next(k['correct_option_id'] for k in item.frozen_private_snapshot['mcqs'] if k['id']==q['id'])) for q in item.frozen_public_snapshot['mcqs']}; resp=AssessmentResponse(assessment_instance_id=item.id,response_text=sr.response_text,response_format="plain",client_action_id=uuid.uuid4(),structured_response={**sr.structured_response,"mcq_answers":opts},response_schema_version="v04.native.2"); d.add(resp); a.status="AWAITING_EVALUATION"; s.phase="ASSESSMENT_AWAITING_EVALUATION"; d.commit()
 from solo_harness.db.models import LLMCall; call=LLMCall(session_id=s.id,attempt_id=a.id,assessment_instance_id=item.id,purpose="JUDGE",status="SUCCEEDED",retry_group_id=uuid.uuid4(),retry_number=0,provider="fault",model="fault",generation_parameters={},request_payload={},request_body_text="{}"); d.add(call); d.flush(); j=SubjectiveJudgment(gradable_status="GRADABLE",subjective_points=1,observed_solo_structure="multistructural",material_correctness="partially correct",criterion_evidence=[],misconception_evidence=[],verbatim_quotes=[sr.response_text[:30]],alternative_reasoning_used=False,unverified_claims=[],review_reason=None,score_justification="controlled failure"); before=s.formal_state_id; finalize_v04_evaluation(d,r,s.id,j,call.id); events=d.execute(select(__import__('solo_harness.db.models',fromlist=['ProtocolEvent']).ProtocolEvent).where(__import__('solo_harness.db.models',fromlist=['ProtocolEvent']).ProtocolEvent.session_id==s.id)).scalars().all(); result={"phase":d.get(Session,s.id).phase,"formal_state_unchanged":d.get(Session,s.id).formal_state_id==before,"unresolved_events":[e.payload for e in events if e.event_type=="SECTION_COMPLETED"],"attempt_count":len(d.scalars(select(Attempt).where(Attempt.session_id==s.id)).all())}; assert result['phase']=="SECTION_COMPLETE" and result['formal_state_unchanged'] and result['unresolved_events'][0]['scientific_outcome']=="UNRESOLVED" and result['attempt_count']==1; (c.research_data_dir/"third_failure_trace.json").write_text(json.dumps(result,indent=2),encoding="utf-8"); print(json.dumps(result))
if __name__=="__main__": main()
